"""Entry page for the Wahni Field PWA; field.html is generated by `yarn build`.

Every /field/... route renders this page (see website_route_rules), so direct
links and refreshes work. The page is session specific and never cached.
"""

import json

import frappe

from wahni_solar.field_portal.api import FIELD_ROUTE, get_boot

no_cache = 1


def get_context(context):
    # Canonical entry: /field -> /field/ so it stays inside the worker/manifest scope.
    if frappe.request and frappe.request.path == FIELD_ROUTE.rstrip("/"):
        frappe.local.flags.redirect_location = FIELD_ROUTE
        raise frappe.Redirect
    csrf_token = frappe.sessions.get_csrf_token()
    frappe.db.commit()  # persist the new CSRF token for this session
    context.no_cache = 1
    context.csrf_token = csrf_token
    # JSON (not a Python repr) and "</" escaped so boot text cannot close the script tag.
    context.boot_json = json.dumps(get_boot(), default=str).replace("</", "<\\/")
    return context
